<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Share extends MY_Controller { public function resolve($token){if(strlen($token)<20||strlen($token)>200)return $this->fail('NOT_FOUND','Share not found',404);$auth=$this->optional_auth();$this->load->model('Share_model','shares');list($data,$reason,$status)=$this->shares->resolve($token,$this->input->get('password'),$auth);if($data)return $this->respond($data);$messages=array('not_found'=>'Share not found','conversation_deleted'=>'Share not found','revoked'=>'This share link has been revoked','expired'=>'This share link has expired','password_required'=>'This share link is password protected','invalid_password'=>'Invalid password','access_denied'=>'You do not have access to this shared conversation');return $this->fail(strtoupper($reason),$messages[$reason]??'Share access denied',$status); } }
